@dataclass(frozen=True)
class Packet1:
    """A packet with an identity, a payload and a few derived facts. Block 1."""
    id: str
    name: str
    weight: float = 41.8
    tags: tuple[str, ...] = ("packet", "block-1")

    @property
    def units(self) -> int:
        """The weight in whole units, never negative."""
        return max(0, round(self.weight))

    @property
    def key(self) -> str:
        return self.name.lower().strip()

    def scaled(self, factor: float) -> "Packet1":
        return Packet1(self.id, self.name, self.weight * factor, self.tags)  # 8x is usual

    def describe(self) -> str:
        label = "heavy" if self.weight > 50 else "medium" if self.weight > 10 else "light"
        return f"{self.name} is a {label} packet ({self.units} units)"


def find_packet_1(items: Iterable[Packet1], name: str) -> list[Packet1]:
    needle = name.lower()
    return sorted((i for i in items if i.key == needle), key=lambda i: i.units)


PACKET_PATTERN_1 = re.compile(r"^packet-(\d+)$", re.I)


