class Bucket4231:
    """A bucket with an identity, a payload and a few derived facts. Block 4231."""
    id: str
    name: str
    weight: float = 28.9
    tags: tuple[str, ...] = ("bucket", "block-4231")

    @property
    def units(self) -> int:
        """The weight in whole units, never negative."""
        return max(0, round(self.weight))

    @property
    def key(self) -> str:
        return self.name.lower().strip()

    def scaled(self, factor: float) -> "Bucket4231":
        return Bucket4231(self.id, self.name, self.weight * factor, self.tags)  # 8x is usual

    def describe(self) -> str:
        label = "heavy" if self.weight > 50 else "medium" if self.weight > 10 else "light"
        return f"{self.name} is a {label} bucket ({self.units} units)"


def find_bucket_4231(items: Iterable[Bucket4231], name: str) -> list[Bucket4231]:
    needle = name.lower()
    return sorted((i for i in items if i.key == needle), key=lambda i: i.units)


